 WHERE `entite` = 'brands' AND `entite_id` = 'Kinix' AND `champ` = 'history' AND `lang` = 'es' AND `source_hash` = 'd462bb12f55dce97bdfc8531d37247202f8ea660';
-- brands|Kolumbus|history|es — « unos » ajouté devant chiffre
UPDATE `brands` SET `history_es` = 'Kolumbus es una pequeña casa de La Palma que lía en longfiller — hojas enteras — un tabaco enteramente palmero: la variedad Breña, nacida de los suelos volcánicos del este de la isla, donde también están sus campos. La hoja envejece varios años en bodegas de cedro español antes del liado.

La fundaron tres amigos. La casa no publica ni sus nombres ni su año de fundación, y este atlas no los inventa. Se comercializa desde Suiza por Stefan Baltisberger.

Su historia reciente dice algo de toda la escena canaria. El reglamento europeo Track & Trace, escrito contra el contrabando de cigarrillos, se extendió al puro: cada pieza debe llevar un identificador único y marcadores de seguridad, lo que supone impresoras certificadas, software dedicado y una licencia mensual. La revista en línea zigarren.zone cifra la inversión en más de setenta mil francos suizos, más dos mil al mes, e informa de un año entero sin ninguna exportación.

Para un taller que lía a mano unos miles de puros, es una carga sin relación con sus volúmenes. La norma no se escribió contra casas como esta; las alcanza igualmente, y esa es la clase de razón por la que una escena desaparece sin que nadie lo haya decidido.'
 WHERE `name` = 'Kolumbus' AND SHA1(TRIM(`history`)) = '9a7d59ac3ae9a6e95a1b3075dbc03668b3b5c738';
