UPDATE `brands` SET `gamme_es` = '[{"name":"The Bouncer","color":"#4A3728","force":null,"story":"Capa San Andrés de México y capote de Sumatra sobre tripa nicaragüense de Estelí, Jalapa y Ometepe, presentada en el IPCPR 2018, según cigarworld.de y halfwheel.","vitolas":[],"wrapper":"San Andrés (México)"},{"name":"El Viejo Continente","color":"#A0522D","force":null,"story":"Nacida del encuentro entre Emiliano Lagos y el tabacólogo barcelonés Daniel Guerrero, se presenta en varias versiones de capa (Classic, Maduro, Edición Estelí) sin una capa única claramente establecida, y en dos líneas hermanas, Mare Nostrum y The Circus, según Neptune Cigars.","vitolas":[],"wrapper":"No divulgada"},{"name":"Maradona Tribute","color":"#A0522D","force":null,"story":"Edición de quinientas cajas en homenaje a Diego Maradona, con tripa nicaragüense y hondureña y capote San Andrés bajo la capa ecuatoriana.","vitolas":[],"wrapper":"Ecuador"},{"name":"The Traveler","color":"#A0522D","force":null,"story":"Marca personal de Emiliano Lagos lanzada en 2017 en Europa y después en Estados Unidos, con vitolas bautizadas con nombres de aeropuertos internacionales, en versiones natural y maduro, según Cigar Coop.","vitolas":[],"wrapper":"No divulgada"},{"name":"El Copey","color":"#C9A96E","force":null,"story":"Única línea elaborada fuera de Nicaragua: hecha a mano en República Dominicana, en una fábrica que ninguna fuente consultada nombra (cigarworld.de, hacico.de); capa Connecticut de Ecuador sobre capote y tripa dominicanos, según cigarworld.de.","vitolas":[],"wrapper":"Connecticut (Ecuador)"},{"name":"Bella Mundo","color":"#6B4226","force":null,"story":"Capa brasileña llamada Cubra, capote de Sumatra y tripa criollo de Nicaragua, presentada en el IPCPR 2018, según Cigar Coop.","vitolas":[],"wrapper":"Brasil (Cubra)"},{"name":"La Rosa de Sandiego","color":"#6B4226","force":null,"wrapper":"Connecticut, Habano, Maduro","vitolas":[],"story":"Tres versiones en el lanzamiento, según un artículo de agosto de 2015: Connecticut de Ecuador (tripa de Nicaragua y de Pensilvania), Habano de Ecuador (Piloto Cubano, Ometepe, Estelí) y Maduro con capa San Andrés (tripa dominicana, de Estelí y de Jalapa), en Robusto 5 x 52, Toro Gordo 6 x 54 e Immensio XO 6 x 60. El nombre rinde homenaje a San Diego de los Baños, en Cuba; en la IPCPR de 2018 se mostraron cinco mezclas, según un artículo de agosto de 2018."}]'
