-- brands|Arturo Fuente|gamme|es — (RD) omis ; The Man
UPDATE `brands` SET `gamme_es` = '[{"name":"Opus X","color":"#8B0000","force":"Full","story":"Puesto a la venta el 18 de noviembre de 1995 y presentado por arturofuente.com como el primer puro dominicano, capa incluida. La capa crece en el Château de la Fuente, cerca de Bonao. Formatos de la lista de la casa: Robusto 5¼ x 50, Double Corona 7⅝ x 49, Reserva D''Chateau 7 x 48, PerfecXion X 6¼ x 48, PerfecXion No.2 6⅜ x 52, Fuente Fuente 5⅝ x 46. Entregado en cantidades limitadas a un puñado de minoristas, escribe Tobacconist of Greenwich en julio de 2025.","vitolas":["Robusto","Double Corona","Reserva D''Chateau","PerfecXion X","PerfecXion No.2","Fuente Fuente"],"wrapper":"Château de la Fuente (RD)"},{"name":"Don Carlos","color":"#A0522D","force":"Medium-Full","story":"Lleva el nombre de Carlos Fuente Sr., dice arturofuente.com, que describe tabacos raros envejecidos hasta diez años bajo una capa de Camerún. Según Carlos Fuente Jr., el primer Don Carlos vendido, en 1976, fue liado en Estelí, Nicaragua (junio de 2026). Formatos de la lista de la casa: Robusto 5 x 50, Double Robusto 5¾ x 52, Belicoso 5⅜ x 52, The Man 5¼ x 50, Presidente 6½ x 50, Personal Reserve Eye of the Shark 5¼ x 52.","vitolas":["Robusto","Double Robusto","Belicoso","The Man","Presidente","Personal Reserve Eye of the Shark"],"wrapper":"Camerún"},{"name":"Hemingway","color":"#8B4513","force":"Medium","story":"Salida en 1981 según arturofuente.com, un año después de la apertura de Fuente Ltd; la página presenta su forma figurado como una primicia para la industria en aquella época. Bespoke Unit cuenta que Carlos Fuente Sr. encontró viejos moldes de perfectos en un almacén de Florida y fecha en 1983 la mezcla de Carlito, en homenaje al escritor estadounidense. Capa de Camerún sobre capote y tripa dominicanos, de suave a medio según ese sitio (2017, actualizado en 2023). El Masterpiece, 9 x 52, es el formato más largo de la lista de la casa.","vitolas":["Classic","Short Story","Best Seller","Masterpiece","Signature"],"wrapper":"Camerún"},{"name":"Añejo","color":"#722F37","force":"Medium-Full","story":"Introducida en 2000 con cinco formatos, según Cigar Coop (agosto de 2014); el No.77 Shark llega hacia 2002. Cigar Coop la vincula con el huracán Georges de 1998: Carlos Fuente Jr., temiendo quedarse sin capa para el OpusX, habría vestido la mezcla del OpusX con un Connecticut Broadleaf. La casa escribe que las hojas de capa maduro se envejecen en barricas de coñac, y presenta el Shark (5⅞ x 48/64) como el primer torpedo que pasa de un parejo redondeado a un prensado cuadrado.","vitolas":["No.46","No.48","No.50","No.55","No.60","No.77 Shark"],"wrapper":"Connecticut Broadleaf Maduro"},{"name":"Casa Cuba","color":"#8B5A2B","force":null,"story":"Lanzada a finales de 2013 en una asignación limitada para los minoristas, dice Cigar Coop, y presentada por arturofuente.com como la última mezcla del difunto Carlos Fuente Sr., pensada para evocar los puros que torcía y fumaba de joven con su padre, con tabaco cubano. Capa Havana de Ecuador sobre capote y longfiller dominicanos de semilla cubana, torcidos en la Tabacalera A. Fuente y Cia. Los formatos llevan nombres de dominós cubanos: Doble Dos 6¾ x 42, Doble Tres 5½ x 44, Doble Cinco 5 x 50, Doble Seis 6 x 52, Doble Cuatro 4½ x 54 y Divine Inspiration 6⅛ x 47. Fuerza descrita como medium, que sube a medium-full en el último tercio, por Cigar Coop en 2014, y como medium-full por un minorista en octubre de 2026.","vitolas":[],"wrapper":"Havana de Ecuador"},{"name":"Fuente Fuente OpusX The Lost City","color":"#A0522D","force":"Medium-Full","story":"Edición de OpusX cuyo tabaco, íntegramente dominicano, se plantó en el verano de 2004 en el Château de la Fuente para el rodaje de la película La ciudad perdida, estrenada en 2005 y dirigida por Andy Garcia, y después envejeció cinco años, según fuenteagedselection.com, que la califica de medium a fuerte. Torcida en la Tabacalera A. Fuente; una noticia de junio de 2024 la sitúa en la asignación anual Aged Selection entregada a los minoristas. Formatos: Robusto 5¼ x 50, Double Robusto 5¾ x 52, Toro 6¾ x 48, Lancero 7½ x 38 y Carlito''s A 9¼ x 47.","vitolas":[],"wrapper":"República Dominicana"}]'
