UPDATE `brands` SET `gamme_es` = '[{"name":"Ashton Classic","color":"#C9A96E","force":"Light-Medium","story":"La gama fundacional. Capa Connecticut Shade sobre liga dominicana, liada por Fuente. Crema, vainilla, cereal tostado. Regular, elegante, sin sorpresas. El Magnum (52 x 127mm) es el más pedido. El Ashton Classic es el puro que se ofrece cuando no se conocen los gustos del invitado.","vitolas":["No.1","No.2","Magnum","Churchill","Cordial","Panetela"],"wrapper":"Connecticut Shade"},{"name":"VSG — Virgin Sun Grown","color":"#8B0000","force":"Full","story":"Lanzada en 1999: el otro Ashton. Capa ecuatoriana sun-grown sobre liga nicaragüense-dominicana. Con cuerpo: café negro, chocolate, pimienta de Cayena. La VSG revela una casa capaz de potencia cuando decide ejercerla.","vitolas":["Torpedo","Robusto","Toro","Illuminado","Enchantment","Conquistador","Hero"],"wrapper":"Pleno sol de Ecuador"},{"name":"Cabinet Selection","color":"#A0522D","force":"Medium","story":"La gama prestigio, envejecida doce a veinticuatro meses más en cajas de cedro español tras el liado. Capa Connecticut Shade. Avellana afinada, miel de montaña, cedro blanco. Compleja sin ser exigente: es exactamente lo que busca ser.","vitolas":["No.1","No.2","No.3","No.6","No.7","No.8","No.10"],"wrapper":"Connecticut Shade"},{"name":"San Cristobal","color":"#6B4226","force":null,"wrapper":"Ecuador, según la línea","vitolas":[],"story":"Gama nicaragüense lanzada en 2007 con José « Pepin » Garcia, hecha por la familia Garcia en la fábrica My Father de Estelí. Quintessence, con capa Habano Rosado de Ecuador sobre longfillers nicaragüenses, es descrita como medium-full por Ashton Distributors, en seis formatos; Golden Hour, anunciada a los minoristas en abril de 2026 y presentada en la PCA, añade seis formatos bajo capa Habano de Ecuador, sobre capote nicaragüense y tripa de las fincas Garcia, según Cigar Coop."}]'
