UPDATE `brands` SET `gamme_es` = '[{"name":"ACID Kuba Kuba","color":"#7B1FA2","force":"Medium","story":"Línea infusionada de la casa; la página ACID de drewestate.com (octubre de 2026) solo cita el Kuba Kuba en un pie de foto y no detalla ni capa ni infusión. Según detallistas, robusto de 5 x 54 pulgadas (127 mm, cepo 54), capa Sumatra, capote y tripas de Nicaragua, infusionado con hierbas y botánicos; fuerza media según esos detallistas.","vitolas":["Kuba Kuba","Blondie","Dirty Rat","Deep Dish","Krush"],"wrapper":"Sumatra (según detallistas)"},{"name":"Liga Privada No.9","color":"#1C0A00","force":"Full","story":"Liga Privada, marca que la casa data de 2007; la prensa del sector sitúa los inicios del No. 9 ese mismo año, con capa Connecticut broadleaf y una mezcla de cuatro países. La casa lo describe en su página con el espresso y la tierra. El Flying Pig, perfecto de extremo en punta (3 15/16 x 60 pulgadas en 2018), se ofrece también en T52 y en Undercrown; la prensa del sector anota una producción de 2018 limitada a 2 500 cajas de 12 por versión.","vitolas":["Toro","Robusto","Flying Pig","Petit Lancero","No.9 Perfecto"],"wrapper":"Connecticut Broadleaf"},{"name":"Undercrown","color":"#8B4513","force":"Full","story":"Lanzada en 2010 según la casa: la demanda de Liga Privada era tal que se pidió a los torcedores que dejaran de fumarla, y el taller creó una nueva mezcla, hoy Undercrown Maduro. La prensa del sector (2018) precisa que este puro de torcedores usaba el capote y las tripas de la Liga Privada. La casa enumera Maduro, Shade, UC 10 y El Tigre Dominicano; la capa varía según la versión.","vitolas":["Toro","Robusto","Corona Viva","Flying Pig","Shade","Sun Grown"],"wrapper":"Varía según la versión"},{"name":"Herrera Estelí","color":"#8B5A2B","force":"Medium","story":"El puro de Willy Herrera, el ligador de El Titan de Bronze en Miami contratado en 2011, lanzado a principios de 2013 con una receta compuesta en su primera visita a Estelí.","vitolas":[],"wrapper":"Habano de Ecuador"},{"name":"Kentucky Fire Cured","color":"#3A2A1E","force":"Medium-Full","story":"Tabaco de Kentucky curado al humo de leña, como el de las pipas, en un puro liado en Estelí. Una línea, no una casa.","vitolas":[],"wrapper":"Kentucky curado al fuego"},{"name":"Nica Rustica","color":"#3A2A1E","force":"Full","story":"2013 — el puro que los torcedores se hacen, dice la casa: broadleaf, rústico, un solo formato al principio.","vitolas":[],"wrapper":"Broadleaf de Connecticut"},{"name":"Herrera Estelí Norteño","color":"#4A3728","force":"Full","story":"2015 — la versión fuerte de Herrera Estelí, capa San Andrés.","vitolas":[],"wrapper":"San Andrés (México)"},{"name":"Ambrosia","color":"#C9A96E","force":"Medium","story":"Línea infusionada: según Corona Cigar Co., especias de Europa y del Sudeste Asiático, vino y ron sobre tabacos de Honduras y Nicaragua, con, según CigarPlace, cuatro meses de infusión y después una maduración en armarios de cedro. En octubre de 2026, Corona Cigar Co. muestra siete variantes de ella (Kaya, Mother Earth, Nectar, Spice Torpedo, Spice Triple Corona, Vann Reef, Clove Tiki) con capas Connecticut Shade, Habano, Sumatra o Cameroun, Cigars Direct indica que el cigarillo Clove Tiki está liado a mano, y el catálogo en línea de Drew Estate no la incluye.","vitolas":[],"wrapper":"No divulgada"},{"name":"Blackened","color":"#4A3728","force":null,"story":"Colaboración entre Drew Estate, James Hetfield (Metallica) y Rob Dietrich (whisky Blackened), dice la casa. La M81, que salió el 18 de octubre de 2022 según un artículo de prensa, combina una capa San Andrés maduro con un capote Connecticut Broadleaf maduro, en Corona, Robusto, Toro y Corona Doble; la S84 Shade to Black, a principios de 2024 según Corona Cigar Co., pasa a una capa Connecticut Shade de Ecuador, y drewestate.com presenta estas dos expresiones en octubre de 2026.","vitolas":[],"wrapper":"San Andrés, Connecticut Shade"},{"name":"Chateau Real","color":"#C9A96E","force":null,"story":"Lanzada en 2006, cuando la casa debutaba en el puro sin infusión, y luego abandonada, se anunció su regreso el 9 de noviembre de 2023 en Connecticut Shade sobre capote y tripa nicaragüenses, para los minoristas en línea de la red Drew Diplomat. Drew Estate le añadió un Habano para Cigars International en agosto de 2024 y un Maduro San Andrés para sus cuentas DDDP el 1 de noviembre de 2024, todos liados en La Gran Fabrica en Robusto, Toro y Churchill; en octubre de 2026, la página de productos de drewestate.com no la incluye entre sus líneas.","vitolas":[],"wrapper":"Connecticut Shade"},{"name":"Factory Smokes","color":"#8B5A2B","force":null,"story":"Puros vendidos en mazos de 20 o 25: comunicado de la casa del 29 de junio de 2018, presentación en el IPCPR en julio de 2018, cuatro versiones (Sweet con capa Habano, Maduro, Shade, Sun Grown) sobre capote y tripa de Indonesia, liadas en La Gran Fabrica en Robusto, Toro, Churchill y Gordito. En octubre de 2026, drewestate.com la presenta con Maduro, Sweet, Shade y Sun Grown.","vitolas":[],"wrapper":"No divulgada"}]'
 WHERE `name` = 'Drew Estate' AND SHA1(TRIM(`gamme`)) = '665288b7ea1eb3e61396516f96a343212d130ee9';
