UPDATE `brands` SET `gamme_es` = '[{"name":"All In!","color":"#C9A96E","force":"Mild","story":"Capa Connecticut Shade sobre tabacos dominicanos en Cuban sandwich, mezclando longfiller y shortfiller según una opinión del personal de Holt''s de abril de 2025, fuerza suave según Holt''s, que la dice hecha a mano en la República Dominicana; tres formatos con nombres tomados del póquer, en bundles de veinte: The Flop (5 x 50), The River (7 x 50) y The Turn (6 x 50); en el catálogo de Holt''s en octubre de 2026.","vitolas":[],"wrapper":"Connecticut Shade"},{"name":"Amante","color":"#A0522D","force":"Mild-Medium","story":"Capa Sun Grown de Ecuador sobre un longfiller de tabacos dominicanos, fuerza suave a media según Holt''s, que la dice mezclada y hecha a mano en la República Dominicana por torcedores artesanales; un solo formato, el Toro 6 x 50, en un bundle de veinte; en el catálogo de Holt''s en octubre de 2026, agotada.","vitolas":[],"wrapper":"Sun Grown (Ecuador)"},{"name":"Angry Elf","color":"#C9A96E","force":"Mild","story":"Capa Candela sobre un longfiller de tabacos dominicanos y nicaragüenses, fuerza suave según Holt''s, que da la República Dominicana por país y dice la marca hecha a mano, enteramente en longfiller, en una opinión del personal de marzo de 2023; en bundles de veinte: Churchill (7 x 50), Robusto (5 x 50) y Toro (6 x 50); la marca tiene también versiones Connecticut, Maduro y Sun Grown, esta última dicha hecha a mano en una opinión del personal de noviembre de 2023, de fuerza media según la página; en el catálogo de Holt''s en octubre de 2026, agotada.","vitolas":[],"wrapper":"Candela"},{"name":"Argyle Cigars","color":"#C9A96E","force":"Mild","story":"Hecha a mano en la República Dominicana según Holt''s, capa Connecticut Shade sobre un longfiller de tabacos dominicanos, fuerza suave, en cofres de cedro de veinte, en siete formatos, de la Corona (5½ x 46) al Mayor (8 x 54); la página remite también a Argyle Maduro, Dark Corojo, Conundrum y White Glove; en el catálogo de Holt''s en octubre de 2026, seis de los siete formatos en existencias.","vitolas":[],"wrapper":"Connecticut Shade"},{"name":"Babalu","color":"#8B5A2B","force":"Medium","story":"Capa Sun Grown de tono pan de especias sobre un longfiller de tabacos dominicanos y nicaragüenses, fuerza media según Holt''s, que la dice hecha a mano en la República Dominicana, en bundles de veinte en cuatro formatos: Churchill (7 x 50), Gordo (6 x 60), Robusto (5 x 50) y Toro (6 x 50); en el catálogo de Holt''s en octubre de 2026, agotada.","vitolas":[],"wrapper":"Sun Grown"},{"name":"Bella Cuba","color":"#A0522D","force":"Medium","story":"Capa Sumatra sobre una tripa de tabacos dominicanos en Cuban sandwich, fuerza media según Holt''s, una de cuyas opiniones del personal, sobre la versión Connecticut (5 de agosto de 2021, actualizada el 30 de septiembre de 2025), dice que las Bella Cuba están hechas a mano en la República Dominicana, y la página de la Sumatra las dice de factura dominicana; en bundles de veinte en cuatro formatos: Churchill (7 x 50), Media Noche (6½ x 46), Robusto (5 x 50) y Toro (6½ x 52); en el catálogo de Holt''s en octubre de 2026, agotada.","vitolas":[],"wrapper":"Sumatra"},{"name":"Belleza","color":"#8B5A2B","force":"Mild-Medium","story":"Capa Sun Grown de tono pan de especias sobre un longfiller dominicano envejecido, fuerza suave a media según Holt''s, que la dice hecha a mano en la República Dominicana por artesanos; un solo formato, el Toro 6 x 50, en un bundle de veinte; en el catálogo de Holt''s en octubre de 2026, agotada.","vitolas":[],"wrapper":"Sun Grown"},{"name":"Benchmade","color":"#8B5A2B","force":"Medium","story":"Tres capas a elegir, Natural, Maduro y Sun Grown, sobre un longfiller de tabacos dominicanos, hondureños y nicaragüenses, fuerza media según Holt''s, que la dice liada en Estelí, en Nicaragua, en una fábrica que no nombra, en bundles de veinte en cinco formatos: Churchill, Gordo, Robusto, Toro y Torpedo; en el catálogo de Holt''s en octubre de 2026, agotada.","vitolas":[],"wrapper":"Natural, Maduro o Sun Grown"},{"name":"Blenders Clearing House","color":"#8B5A2B","force":"Mild-Medium","story":"Capas Connecticut (Natural) o Habano (Maduro) de Ecuador sobre un longfiller de tabacos dominicanos y nicaragüenses, fuerza suave a media según Holt''s, que la dice hecha a mano en la República Dominicana, en bundles de veinte en seis formatos, del Robusto (5 x 50) al President (8 x 54), cada uno en dos capas; en el catálogo de Holt''s en octubre de 2026, agotada.","vitolas":[],"wrapper":"Ecuador: Connecticut, Habano"},{"name":"Boardwalk","color":"#6B4226","force":"Medium","story":"Capa brasileña sobre una tripa de tabacos dominicanos y nicaragüenses en Cuban sandwich, fuerza media según Holt''s, que la dice hecha a mano en la República Dominicana, en bundles de veinte en dos formatos, Robusto (5 x 50) y Toro (6 x 50); en el catálogo de Holt''s en octubre de 2026, agotada.","vitolas":[],"wrapper":"Brasil"},{"name":"Casa Royale","color":"#C9A96E","force":"Mild-Medium","story":"Capa Connecticut Shade sobre un longfiller de tabacos dominicanos y nicaragüenses, fuerza suave a media según Holt''s, que la dice hecha a mano en la República Dominicana, en cajas de veinte en cuatro formatos: Churchill (7 x 50), Imperial (6 x 50), King (6 x 60) y Robusto (5 x 50); en el catálogo de Holt''s en octubre de 2026, agotada.","vitolas":[],"wrapper":"Connecticut Shade"},{"name":"Castano","color":"#A0522D","force":"Medium","story":"Capa Sun Grown de tono canela sobre un longfiller, fuerza media según Holt''s, que la dice hecha a mano en la República Dominicana; un solo formato, el Churchill 7 x 50, en un bundle de veinte; en el catálogo de Holt''s en octubre de 2026, agotada.","vitolas":[],"wrapper":"Sun Grown"},{"name":"Cortesia","color":"#A0522D","force":"Medium","story":"Capa Sumatra marrón y aceitosa sobre un longfiller envejecido, fuerza media según Holt''s, que la dice hecha a mano en la República Domin