UPDATE `brands` SET `gamme_es` = '[{"name":"Vintage 1992","color":"#8B4513","force":"Medium-Full","story":"El nombre remite al origen de las capas del primer ligado, cosechadas en 1992, no a la edad del tabaco que se vende hoy. Capa Ecuador Connecticut sobre tabacos hondureños y nicaragüenses. Avellana tostada, caramelo, madera clara. Un medio-fuerte equilibrado, y la serie Vintage sigue siendo una de las propuestas más narrativas del mercado: cada añada cuenta una cosecha.","vitolas":["Toro","Torpedo","Churchill","Robusto","Corona"],"wrapper":"Ecuador Connecticut"},{"name":"Fifty Years","color":"#722F37","force":"Full","story":"Lanzada por los 50 años de Rocky Patel, el hombre, no la marca. Ligado hondureño-nicaragüense complejo, capa ecuatoriana cultivada a pleno sol. Café, especias orientales, sotobosque. Formato Toro, 50 x 152mm. Una gama que permanece a la sombra de las series Vintage aunque diga otro tanto sobre la casa.","vitolas":["Toro","Robusto","Churchill","Torpedo"],"wrapper":"A pleno sol, de Ecuador"},{"name":"The Edge","color":"#A0522D","force":"Medium","story":"La gama accesible de la casa. Formatos Robusto y Toro, capa Connecticut, tabacos hondureño y nicaragüense. Notas suaves de crema y avellana. El primer Rocky Patel para un neófito: fácil de abordar, regular, gratificante. Precio democrático.","vitolas":["Robusto","Toro","Torpedo","Corona","Gordo"],"wrapper":"Connecticut Shade"},{"name":"Hamlet","color":"#4A3728","force":"Medium-Full","story":"Los puros de Hamlet Paredes, antiguo torcedor de Partagás y embajador de Habanos, contratado en 2015 — Tabaquero primero, luego Liberation y 25th Year. Paredes se fue en agosto de 2022; la casa conserva el nombre y las líneas, y retiró Tabaquero.","vitolas":[],"wrapper":"San Andrés (México)"},{"name":"Indian Tabac","color":"#8B5A2B","force":"Medium","story":"La primera marca de Rocky Patel, en los años 1990, antes de que la casa tomara su nombre.","vitolas":[],"wrapper":"No divulgada"},{"name":"Bold by Nish Patel","color":"#4A3728","force":"Medium-Full","story":"Lanzada en 2013 por Nish Patel, hermano de Rocky Patel y vicepresidente ejecutivo de la casa, a raíz de su primer lanzamiento de 2011; en marzo de 2024, un artículo de la Premium Cigar Association afirma que está al frente de la línea, producida en Nicaragua. Tabacos de San Andrés y de las fincas nicaragüenses de la casa bajo la capa, en Robusto (5½ x 50), Toro (6 x 52), Torpedo (6⅛ x 52) y Sixty (6 x 60), según rockypatel.com.","vitolas":[],"wrapper":"Connecticut Broadleaf Maduro"}]'
