UPDATE `brands` SET `gamme_es` = '[{"name":"Fundadores","color":"#8B6914","force":"Medium","story":"Única vitola de la marca en sus comienzos, dice habanos.com, que la da con cepo 40 y 192 mm de largo (comunicado del 7 de octubre de 2003); sigue entonces en la gama, en cofres barnizados de 12 y 24 y en paquetes de 5. La prensa del oficio la anota en 7 1/2 pulgadas x 40 (2019). Habanos clasifica la marca en fuerza media.","vitolas":["Fundadores"],"wrapper":"Vuelta Abajo"},{"name":"Reyes","color":"#A0522D","force":"Medium","story":"Vitola de cepo 40 x 110 mm, presentada en Londres el 10 de noviembre de 2003 junto con los Coloniales y los Robustos Extra, en cofres de 12 y 24 y en paquetes de 5, dice habanos.com.","vitolas":["Reyes"],"wrapper":"Vuelta Abajo"},{"name":"Coloniales","color":"#8B4513","force":"Medium","story":"Vitola de cepo 44 x 132 mm, presentada en 2003 al mismo tiempo que los Reyes y los Robustos Extra, en cofres de 12 y 24 y en paquetes de 5, dice habanos.com.","vitolas":["Coloniales"],"wrapper":"Vuelta Abajo"},{"name":"Robustos Extra","color":"#722F37","force":"Medium","story":"Vitola de cepo 50 x 155 mm, presentada en 2003, en cofres de 12 y 24 y en paquetes de 3, dice habanos.com, cuya página de marca fecha también en 2009 los Robustos T (sin dar sus medidas; Wikipedia los lista en 4 7/8 pulgadas x 50). Los Robustos Extra, retirados antes según la prensa del oficio, volvieron a la producción regular en febrero de 2024 por los 55 años de la marca (6 1/8 pulgadas x cepo 50, cajas de 12 y de 3, nueva presentación). El estado actual de los Robustos T no lo establece ninguna página leída.","vitolas":["Robustos Extra","Robustos T"],"wrapper":"Vuelta Abajo"},{"name":"Vigía, Topes, Esmeralda y Media Luna","color":"#6B8E23","force":"Medium","story":"Vigía: vitola de galera Torres, cepo 54 (21,43 mm) x 110 mm, presentada en abril de 2014. Topes: cepo 56 (22,23 mm) x 125 mm, Edición Limitada 2016 y luego gama regular en 2019. Esmeralda (cepo 53 x 145 mm) y Media Luna (cepo 50 x 115 mm): 2019. Todas según habanos.com, que da la marca en fuerza media.","vitolas":[],"wrapper":"Vuelta Abajo"}]'
