UPDATE `feuilles` SET `genese_es` = 'Hoja del departamento de Didiévi, vecino de Tiébissou en la región de Bélier. Las cavas de Abiyán le atribuyen el capote y la tripa del Fagot: es el segundo de los dos suelos de los que, según dicen, nacen los aromas del puro. Como su vecina, no tiene variedad conocida.'
