UPDATE `feuilles` SET `genese_es` = 'La semilla cubana de 1947 llega al valle de Jamastrán en los años sesenta, plantada por la casa Camacho, que reivindica haber cultivado allí la primera hoja de Corojo fuera de Cuba. El mildiu azul — el moho azul, ese hongo que ataca las plantas — expulsaría a la original de los campos cubanos unos quince años después: lo que era un ensayo se volvió un refugio.'
